{
  "claims": [
    {
      "claim_text": "Before PostgreSQL 9.4, freezing replaced a row's insertion XID with FrozenTransactionId.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states this directly.",
      "citations": [
        {"index": 0, "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId"}
      ]
    },
    {
      "claim_text": "On a cluster still running 9.3, frozen rows show up with an xmin of 2.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 says pre-9.4 freezing replaced insertion XID with FrozenTransactionId, and rows with xmin equal to FrozenTransactionId (2) may be found; 9.3 is before 9.4.",
      "citations": [
        {"index": 0, "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId"},
        {"index": 0, "quote": "rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions"}
      ]
    },
    {
      "claim_text": "Newer versions only set a flag bit and keep the original xmin.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states newer versions just set a flag bit, preserving the row's original xmin.",
      "citations": [
        {"index": 0, "quote": "Newer versions just set a flag bit, preserving the row's original xmin for possible forensic use."}
      ]
    },
    {
      "claim_text": "Newer versions set a flag bit mainly to reduce WAL volume.",
      "verdict": "UNSUPPORTED",
      "reasoning": "Passage 0 gives 'for possible forensic use' as the reason for preserving xmin; it does not mention reducing WAL volume.",
      "citations": []
    },
    {
      "claim_text": "A cluster that was pg_upgrade'd from 9.3 can never contain rows with xmin 2.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 explicitly says rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions.",
      "citations": [
        {"index": 0, "quote": "However, rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions."}
      ]
    },
    {
      "claim_text": "System catalogs can contain rows with xmin 1, BootstrapTransactionId, which is treated as older than every normal XID.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states this directly.",
      "citations": [
        {"index": 1, "quote": "system catalogs may contain rows with xmin equal to BootstrapTransactionId (1), indicating that they were inserted during the first phase of initdb."},
        {"index": 1, "quote": "Like FrozenTransactionId, this special XID is treated as older than every normal XID."}
      ]
    },
    {
      "claim_text": "pg_xact stores two bits of commit status per transaction.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states the commit status uses two bits per transaction.",
      "citations": [
        {"index": 2, "quote": "The commit status uses two bits per transaction"}
      ]
    },
    {
      "claim_text": "The default horizon of 200 million transactions costs about 50MB of pg_xact storage.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states the default, 200 million transactions, translates to about 50MB of pg_xact storage.",
      "citations": [
        {"index": 2, "quote": "(The default, 200 million transactions, translates to about 50MB of pg_xact storage and about 2GB of pg_commit_ts storage.)"}
      ]
    },
    {
      "claim_text": "Raising autovacuum_freeze_max_age to its two-billion maximum would grow pg_xact to roughly 2GB.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 2 says at the two-billion maximum, pg_xact can be expected to grow to about half a gigabyte and pg_commit_ts to about 20GB; 2GB is the pg_commit_ts figure at the default, not pg_xact at maximum.",
      "citations": [
        {"index": 2, "quote": "if autovacuum_freeze_max_age is set to its maximum allowed value of two billion, pg_xact can be expected to grow to about half a gigabyte and pg_commit_ts to about 20GB."}
      ]
    },
    {
      "claim_text": "Multixact member storage can grow to about 20GB before wraparound.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states this directly.",
      "citations": [
        {"index": 6, "quote": "The members storage area can grow up to about 20GB before reaching wraparound."}
      ]
    },
    {
      "claim_text": "Aggressive vacuums start running more often once multixact member storage passes about half of 20GB (about 10GB).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says if storage occupied by multixact members exceeds about 10GB, aggressive vacuum scans occur more often; 10GB is about half of 20GB.",
      "citations": [
        {"index": 6, "quote": "if the storage occupied by multixacts members exceeds about 10GB, aggressive vacuum scans will occur more often for all tables"}
      ]
    },
    {
      "claim_text": "XID exhaustion and MXID exhaustion both block all write transactions.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 7 says XID exhaustion blocks all write transactions, but MXID exhaustion only blocks a subset involving row locks that require an MXID.",
      "citations": [
        {"index": 7, "quote": "XID exhaustion will block all write transactions, but MXID exhaustion will only block a subset of write transactions, specifically those that involve row locks that require an MXID."}
      ]
    }
  ]
}
